{"title": "Requests and mean latency per 10 s", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "ml-predictions",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 0,
        "aggs": {
          "t": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "10s"
            },
            "aggs": {
              "latency": {
                "avg": {
                  "field": "latency_ms"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.t.buckets"
    }
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "title": null
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "opacity": 0.6,
        "size": 22
      },
      "encoding": {
        "y": {
          "field": "doc_count",
          "type": "quantitative",
          "title": "requests"
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#e7664c",
        "point": true
      },
      "encoding": {
        "y": {
          "field": "latency.value",
          "type": "quantitative",
          "title": "mean latency (ms)"
        }
      }
    }
  ],
  "resolve": {
    "scale": {
      "y": "independent"
    }
  }
}"}}

{"title": "Mean prediction per 10 s (output drift)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "ml-predictions",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 0,
        "aggs": {
          "t": {
            "date_histogram": {
              "field": "@timestamp",
              "fixed_interval": "10s"
            },
            "aggs": {
              "pred": {
                "avg": {
                  "field": "prediction"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.t.buckets"
    }
  },
  "mark": {
    "type": "line",
    "point": true
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "pred.value",
      "type": "quantitative",
      "title": "mean predicted progression",
      "scale": {
        "zero": false
      }
    }
  }
}"}}

{"title": "PSI per feature (>= 0.2 = drift alert)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "index": "ml-drift",
      "%context%": true,
      "%timefield%": "@timestamp",
      "body": {
        "size": 1000,
        "_source": [
          "@timestamp",
          "psi",
          "prediction_psi"
        ]
      }
    },
    "format": {
      "property": "hits.hits"
    }
  },
  "transform": [
    {
      "calculate": "toDate(datum._source['@timestamp'])",
      "as": "time"
    },
    {
      "fold": [
        "_source.psi.age",
        "_source.psi.sex",
        "_source.psi.bmi",
        "_source.psi.bp",
        "_source.psi.s1",
        "_source.psi.s2",
        "_source.psi.s3",
        "_source.psi.s4",
        "_source.psi.s5",
        "_source.psi.s6",
        "_source.prediction_psi"
      ]
    },
    {
      "calculate": "replace(replace(datum.key, '_source.psi.', ''), '_source.prediction_psi', 'prediction')",
      "as": "feature"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "line",
        "point": true
      },
      "encoding": {
        "x": {
          "field": "time",
          "type": "temporal",
          "title": null
        },
        "y": {
          "field": "value",
          "type": "quantitative",
          "title": "PSI"
        },
        "color": {
          "field": "feature",
          "type": "nominal",
          "scale": {
            "scheme": "tableau20"
          }
        },
        "tooltip": [
          {
            "field": "feature"
          },
          {
            "field": "value",
            "format": ".3f"
          },
          {
            "field": "time",
            "type": "temporal",
            "timeUnit": "hoursminutesseconds"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "red",
        "strokeDash": [
          6,
          4
        ]
      },
      "encoding": {
        "y": {
          "datum": 0.2
        }
      }
    }
  ]
}"}}
